message:
Running command: cat > /tmp/driver.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "fuzz.h"

int fuzzXmlInit(int *argc, char ***argv);
int fuzzXml(const char *data, size_t size);

int main(int argc, char **argv) {
    FILE *f;
    long sz;
    char *buf;
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 2; }
    f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 2; }
    fseek(f, 0, SEEK_END);
    sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = malloc(sz);
    if (fread(buf, 1, sz, f) != (size_t)sz) { perror("fread"); return 2; }
    fclose(f);
    fuzzXmlInit(NULL, NULL);
    fuzzXml(buf, sz);
    free(buf);
    printf("no crash\n");
    return 0;
}
EOF
cd /workspace/repo-vul/src-vul/fuzz && \
  gcc -O1 -g -fsanitize=address -fno-omit-frame-pointer \
      -I.. -I../include -I. \
      -DFUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION \
      -DHAVE_XML_FUZZER \
      /tmp/driver.c xml.c fuzz.c \
      ../.libs/libxml2.a -lz -llzma -lm -lpthread \
      -o /tmp/driver 2>&1 | tail -20
echo "build exit=$?"; ls -la /tmp/driver 2>/dev/null

